const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (data.length < 5) process.exit(0);

const M = parseInt(data[1], 10);
const K = parseInt(data[2], 10);
const pattern = data[3];

const words = [];
for (let i = 0; i < M; i++) {
    words.push(data[4 + i].split('').sort());
}

let P = parseInt(data[4 + M], 10);

const CAP = 1000000000;
const blocks = new Array(M);
let cur = 1;

for (let i = M - 1; i >= 0; i--) {
    blocks[i] = cur;
    cur *= K;
    if (cur > CAP) cur = CAP;
}

let answer = '';
let idx = 0;

for (let i = 0; i < pattern.length; i++) {
    const ch = pattern[i];

    if (ch === '#') {
        const block = blocks[idx];
        const q = Math.floor((P - 1) / block);

        answer += words[idx][q];
        P = ((P - 1) % block) + 1;
        idx++;
    } else {
        answer += ch;
    }
}

console.log(answer);
